package compromise

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"fmt"
	"sync"
)

// model.json.gz is generated by tools/dump-model from the JS compromise
// package. It holds data only; every algorithm that reads it lives in Go.
//
//go:embed model/model.json.gz
var modelGz []byte

// CompromiseVersion is the JS compromise release whose model is embedded.
func CompromiseVersion() string { return getModel().Version }

type tagInfo struct {
	Not      []string `json:"not"`
	Parents  []string `json:"parents"`
	Children []string `json:"children"`
}

// tagList is a lexicon value: compromise allows a single tag or a list.
type tagList []string

func (t *tagList) UnmarshalJSON(b []byte) error {
	if len(b) > 0 && b[0] == '"' {
		var s string
		if err := json.Unmarshal(b, &s); err != nil {
			return err
		}
		*t = tagList{s}
		return nil
	}
	var arr []string
	if err := json.Unmarshal(b, &arr); err != nil {
		return err
	}
	*t = arr
	return nil
}

type contraction struct {
	Word   *string  `json:"word"`
	After  *string  `json:"after"`
	Before *string  `json:"before"`
	Out    []string `json:"out"`
}

type jsRegexJSON struct {
	Source string  `json:"source"`
	Flags  string  `json:"flags"`
	Tag    tagList `json:"tag"`
	Reason string  `json:"reason"`
}

type clueSet struct {
	BeforeTags  map[string]string `json:"beforeTags"`
	AfterTags   map[string]string `json:"afterTags"`
	BeforeWords map[string]string `json:"beforeWords"`
	AfterWords  map[string]string `json:"afterWords"`
}

type neighbourModel struct {
	LeftTags   [][2]string `json:"leftTags"`
	LeftWords  [][2]string `json:"leftWords"`
	RightTags  [][2]string `json:"rightTags"`
	RightWords [][2]string `json:"rightWords"`
}

type rawModel struct {
	Version string `json:"version"`
	One     struct {
		TagSet          map[string]tagInfo `json:"tagSet"`
		Contractions    []contraction      `json:"contractions"`
		NumberSuffixes  []string           `json:"numberSuffixes"`
		Aliases         map[string]string  `json:"aliases"`
		Abbreviations   []string           `json:"abbreviations"`
		Prefixes        []string           `json:"prefixes"`
		Suffixes        []string           `json:"suffixes"`
		PrePunctuation  []string           `json:"prePunctuation"`
		PostPunctuation []string           `json:"postPunctuation"`
		Lexicon         map[string]tagList `json:"lexicon"`
		Unicode         map[string]string  `json:"unicode"`
		Emoticons       []string           `json:"emoticons"`
		MultiCache      map[string]int     `json:"multiCache"`
		FrozenLex       map[string]tagList `json:"frozenLex"`
	} `json:"one"`
	Two struct {
		Switches       map[string]string        `json:"switches"`
		Clues          map[string]clueSet       `json:"clues"`
		Neighbours     neighbourModel           `json:"neighbours"`
		RegexNormal    []jsRegexJSON            `json:"regexNormal"`
		RegexText      []jsRegexJSON            `json:"regexText"`
		RegexNumbers   []jsRegexJSON            `json:"regexNumbers"`
		EndsWith       map[string][]jsRegexJSON `json:"endsWith"`
		SuffixPatterns []map[string]string      `json:"suffixPatterns"`
		PrefixPatterns []map[string]string      `json:"prefixPatterns"`
		OrgWords       []string                 `json:"orgWords"`
		PlaceWords     []string                 `json:"placeWords"`
	} `json:"two"`
	Net struct {
		Matches []netMatchJSON    `json:"matches"`
		Hooks   []json.RawMessage `json:"hooks"`
		Always  []int             `json:"always"`
	} `json:"net"`
}

type tagRegex struct {
	re  *jsRegexp
	tag tagList
}

type model struct {
	Version string

	tagSet          map[string]*tagInfo
	contractions    []contraction
	numberSuffixes  map[string]bool
	aliases         map[string]string
	abbreviations   map[string]bool
	prefixes        map[string]bool
	suffixes        map[string]bool
	prePunctuation  map[string]bool
	postPunctuation map[string]bool
	lexicon         map[string]tagList
	unicode         map[rune]string
	emoticons       map[string]bool
	multiCache      map[string]int
	frozenLex       map[string]tagList

	switches       map[string]string
	clues          map[string]*clueSet
	neighbours     neighbourModel
	regexNormal    []tagRegex
	regexText      []tagRegex
	regexNumbers   []tagRegex
	endsWith       map[rune][]tagRegex
	suffixPatterns []map[string]string
	prefixPatterns []map[string]string
	orgWords       map[string]bool
	placeWords     map[string]bool

	net *net
}

var (
	modelOnce sync.Once
	theModel  *model
)

func getModel() *model {
	modelOnce.Do(func() {
		m, err := loadModel(modelGz)
		if err != nil {
			panic(fmt.Sprintf("compromise: embedded model: %v", err))
		}
		theModel = m
	})
	return theModel
}

func setOf(list []string) map[string]bool {
	out := make(map[string]bool, len(list))
	for _, s := range list {
		out[s] = true
	}
	return out
}

func compileTable(list []jsRegexJSON) ([]tagRegex, error) {
	out := make([]tagRegex, 0, len(list))
	for _, r := range list {
		re, err := compileJSRegexp(r.Source, r.Flags)
		if err != nil {
			return nil, err
		}
		out = append(out, tagRegex{re: re, tag: r.Tag})
	}
	return out, nil
}

func loadModel(gz []byte) (*model, error) {
	zr, err := gzip.NewReader(bytes.NewReader(gz))
	if err != nil {
		return nil, err
	}
	var raw rawModel
	if err := json.NewDecoder(zr).Decode(&raw); err != nil {
		return nil, err
	}
	m := &model{Version: raw.Version}
	m.tagSet = make(map[string]*tagInfo, len(raw.One.TagSet))
	for k, v := range raw.One.TagSet {
		v := v
		m.tagSet[k] = &v
	}
	m.contractions = raw.One.Contractions
	m.numberSuffixes = setOf(raw.One.NumberSuffixes)
	m.aliases = raw.One.Aliases
	m.abbreviations = setOf(raw.One.Abbreviations)
	m.prefixes = setOf(raw.One.Prefixes)
	m.suffixes = setOf(raw.One.Suffixes)
	m.prePunctuation = setOf(raw.One.PrePunctuation)
	m.postPunctuation = setOf(raw.One.PostPunctuation)
	m.lexicon = raw.One.Lexicon
	m.unicode = make(map[rune]string, len(raw.One.Unicode))
	for k, v := range raw.One.Unicode {
		// killUnicode works per UTF-16 unit; every key in the model is one BMP char.
		r := []rune(k)
		if len(r) == 1 {
			m.unicode[r[0]] = v
		}
	}
	m.emoticons = setOf(raw.One.Emoticons)
	m.multiCache = raw.One.MultiCache
	m.frozenLex = raw.One.FrozenLex

	m.switches = raw.Two.Switches
	m.clues = make(map[string]*clueSet, len(raw.Two.Clues))
	for k, v := range raw.Two.Clues {
		v := v
		m.clues[k] = &v
	}
	m.neighbours = raw.Two.Neighbours
	if m.regexNormal, err = compileTable(raw.Two.RegexNormal); err != nil {
		return nil, err
	}
	if m.regexText, err = compileTable(raw.Two.RegexText); err != nil {
		return nil, err
	}
	if m.regexNumbers, err = compileTable(raw.Two.RegexNumbers); err != nil {
		return nil, err
	}
	m.endsWith = make(map[rune][]tagRegex, len(raw.Two.EndsWith))
	for k, v := range raw.Two.EndsWith {
		t, err := compileTable(v)
		if err != nil {
			return nil, err
		}
		r := []rune(k)
		m.endsWith[r[0]] = t
	}
	m.suffixPatterns = raw.Two.SuffixPatterns
	m.prefixPatterns = raw.Two.PrefixPatterns
	m.orgWords = setOf(raw.Two.OrgWords)
	m.placeWords = setOf(raw.Two.PlaceWords)

	n, err := loadNet(raw.Net.Matches, raw.Net.Hooks, raw.Net.Always)
	if err != nil {
		return nil, err
	}
	m.net = n
	return m, nil
}
